window.SKIM_PAPERS["1509.06664"] = {"concepts": [{"id": "conditional-encoding", "name": "Conditional encoding: reading both sentences in one pass", "tier": "minor", "parent": null, "summary": "Instead of embedding a premise and a hypothesis separately and comparing the two vectors, the model reads them as a single left-to-right sequence — premise, then a delimiter, then hypothesis — so the hypothesis is processed conditioned on what was read before it. One recurrent pass over one stream produces one final state, which is all the classifier sees.", "explanation": "The input is laid out as a single token sequence x_1 ... x_N: the L tokens of the premise occupy positions 1..L, a delimiter symbol follows, and the hypothesis tokens run to position N. An LSTM reads the premise portion; a second LSTM reads the delimiter and the hypothesis portion, and the whole thing behaves as one continuous read because the second LSTM's memory is initialized from the first one's final cell state (see the cell-state handoff). Words are represented by fixed word2vec vectors that are not updated during training, except for words absent from the pretrained vocabulary, which are initialized uniformly from (-0.05, 0.05) and trained; unseen words at inference time are assigned fixed random vectors. A linear layer projects each word vector to the LSTM hidden size k, yielding the input vectors x_i, so k is both the embedding-after-projection size and the hidden size. The paper's argument for this layout is that information flows from the premise part of the computation into the hypothesis part, so the model 'does not waste capacity on encoding the hypothesis (in fact it does not need to encode the hypothesis at all)' and can instead check hypothesis words and phrases against a representation of the premise as it goes. One interpretation the authors offer is that the recurrent net is approximating a finite-state automaton for the entailment decision. Nothing about the layout is specific to entailment or to language: it is a generic sequence model requiring no processing beyond tokenization, which the authors point to as making it a candidate for transfer learning. Reported gain over encoding the two sentences independently is 3.3 accuracy points.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 2.2.1 'Conditional Encoding' and Figure 1(A); word-representation details in the same paragraph plus footnote 1; the 'Conditional Encoding' paragraph of Section 4.", "ownerPaper": "1509.06664", "sources": {"paperId": "1509.06664", "note": "Section 2.2.1 'Conditional Encoding' and Figure 1(A); word-representation details in the same paragraph plus footnote 1; the 'Conditional Encoding' paragraph of Section 4.", "sections": [], "pages": []}}, {"id": "premise-hypothesis-delimiter", "name": "The delimiter token between the two sentences", "tier": "minor", "parent": null, "summary": "A dedicated delimiter symbol is inserted between the premise and the hypothesis in the single token stream, so the reader has an explicit in-band signal for where one sentence ends and the other begins.", "explanation": "Because the two sentences are concatenated into one sequence, the model needs some way to know the boundary; the paper's answer is to spend one sequence position on a delimiter, drawn as '::' in the running example. In the figure, the premise 'A wedding party taking pictures' occupies x_1..x_5, the delimiter occupies x_6, and the hypothesis 'Someone got married' occupies x_7..x_9. The delimiter is read by the same recurrence as the rest of the stream — it is an input token, not an architectural component — so it costs no parameters beyond its own embedding and no change to the reader. Its position also serves as the seam at which the cell state from the premise is handed over. The paper treats the hypothesis output vectors as h_7, h_8, h_9 in that example, i.e. the position at which the delimiter is consumed is not counted among the hypothesis positions. The paper does not ablate the delimiter or discuss what happens without one; it is stated as part of the construction.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 2.2.1, sentence beginning 'A second LSTM ... is reading a delimiter and the hypothesis'; Figure 1, where the delimiter appears as '::' at position x_6.", "ownerPaper": "1509.06664", "sources": {"paperId": "1509.06664", "note": "Section 2.2.1, sentence beginning 'A second LSTM ... is reading a delimiter and the hypothesis'; Figure 1, where the delimiter appears as '::' at position x_6.", "sections": [], "pages": []}}, {"id": "cell-state-conditioning-handoff", "name": "Cell-state handoff at the sentence boundary", "tier": "minor", "parent": null, "summary": "Conditioning is implemented by initializing the second LSTM's memory with the last cell state produced while reading the premise, rather than by any comparison or matching layer.", "explanation": "An LSTM carries two things forward at each step: an output vector h_t and a cell state c_t, where c_t = f_t ⊙ c_{t-1} + i_t ⊙ tanh(W_c H + b_c) and h_t = o_t ⊙ tanh(c_t), with H the concatenation of x_t and h_{t-1}. In this model, the premise reader runs to the end of the premise and its final cell state — c_5 in the paper's five-word example — is used as the initial cell state of the reader that consumes the delimiter and the hypothesis. That single assignment is the entire conditioning mechanism: no attention, no concatenation, no learned interaction layer between the two sentences. The consequence is that the whole premise must be compressed into one k-dimensional cell vector before any hypothesis word is seen, which the paper explicitly names as a bottleneck and which motivates the attention extensions it goes on to propose. The two readers may have different parameter matrices W_i, W_f, W_o, W_c ∈ R^{2k×k} and biases in R^k, or may share them; the handoff is the same either way. Because the handoff is just an initialization, the composition is trained end to end by ordinary backpropagation through the joined sequence.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 2.1, Eqs. 1-6 for the LSTM recurrence; Section 2.2.1 ('its memory state is initialized with the last cell state of the previous LSTM (c_5 in the example)'); Figure 1(A). Bottleneck framing in Section 2.3 and the 'Attention' paragraph of Section 4.", "ownerPaper": "1509.06664", "sources": {"paperId": "1509.06664", "note": "Section 2.1, Eqs. 1-6 for the LSTM recurrence; Section 2.2.1 ('its memory state is initialized with the last cell state of the previous LSTM (c_5 in the example)'); Figure 1(A). Bottleneck framing in Section 2.3 and the 'Attention' paragraph of Section 4.", "sections": [], "pages": []}}, {"id": "shared-parameter-single-reader", "name": "Parameter sharing: one reader for the whole stream", "tier": "minor", "parent": null, "summary": "The premise reader and hypothesis reader can share all weights, which makes the model literally one recurrent net sweeping a single delimited sequence, and keeps the parameter count comparable to a single-sentence encoder.", "explanation": "The paper reports two variants: two LSTMs with independent parameters, and a 'shared' variant in which both use the same weights. Sharing was introduced so the parameter count would be comparable to the independent-encoder baseline, which uses one LSTM for both sentences. With hidden size k = 100 the shared variant has 3.8M total parameters, of which 111k are model parameters excluding word representations, versus roughly 10M total and 221k model parameters for the independent-encoder baseline at the same k. The shared variant at k = 100 reaches 80.9 test accuracy; at k = 159 it reaches 81.4; the two-LSTM version at k = 116 reaches 80.9 — so sharing costs nothing measurable here. The word-representation totals are dominated by the 3.65M tunable parameters for the 12.1k words that had no pretrained embedding. The practical reading is that the two-sentence handling adds no architecture: with shared weights the model is a plain sequence reader, and the only thing that makes it a pair model is how the input was serialized.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Table 1 rows 'Conditional encoding, shared' (k = 100 and k = 159) and 'Conditional encoding' (k = 116), columns |θ|_{W+M} and |θ|_M; explained in the first paragraph of Section 4; footnote 1 for the 3.65M tunable word-vector parameters.", "ownerPaper": "1509.06664", "sources": {"paperId": "1509.06664", "note": "Table 1 rows 'Conditional encoding, shared' (k = 100 and k = 159) and 'Conditional encoding' (k = 116), columns |θ|_{W+M} and |θ|_M; explained in the first paragraph of Section 4; footnote 1 for the 3.65M tunable word-vector parameters.", "sections": [], "pages": []}}, {"id": "last-output-vector-classifier", "name": "Classifying from the final output vector", "tier": "minor", "parent": null, "summary": "The prediction is read off the last output vector of the stream: a non-linear projection into the three-class space followed by a softmax, trained with cross-entropy.", "explanation": "After the reader has consumed premise, delimiter and hypothesis, the output vector at the final position — h_9 in the paper's example, h_N in general — is taken as the sentence-pair representation. A non-linear projection maps it into the target space of the three classes ENTAILMENT, NEUTRAL and CONTRADICTION, and a softmax over that gives the class distribution; training minimizes cross-entropy. So the only task-specific parameters outside the reader are the projection into the label space, on the order of k times the number of classes. Regularization is dropout applied only to the inputs and outputs of the network, plus ℓ2 on the weights. In the attention extensions the same head is reused, only fed a different vector: h* = tanh(W_p r + W_x h_N), a non-linear combination of an attention-weighted premise representation r and the same final output vector h_N. The authors note in the qualitative analysis that h_N remains part of the final representation, which is why the model is not forced to rely on the attention-derived part alone.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 2.2.1, final sentence ('for classification we use a softmax layer over the output of a non-linear projection of the last output vector'); Eqs. 10 and 14 for the attentive variants of the same head; footnote 3 for the dropout placement.", "ownerPaper": "1509.06664", "sources": {"paperId": "1509.06664", "note": "Section 2.2.1, final sentence ('for classification we use a softmax layer over the output of a non-linear projection of the last output vector'); Eqs. 10 and 14 for the attentive variants of the same head; footnote 3 for the dropout placement.", "sections": [], "pages": []}}, {"id": "independent-encoding-baseline-contrast", "name": "What one stream buys over two separate encoders", "tier": "minor", "parent": null, "summary": "The alternative it is measured against encodes premise and hypothesis independently into fixed-length vectors and feeds their concatenation to an MLP. Reading one joined stream instead is reported to gain 3.3 accuracy points, with fewer parameters.", "explanation": "In the two-encoder setup, each sentence is mapped independently into a dense fixed-length vector, the two vectors are concatenated, and a multi-layer perceptron on top predicts the class; nothing from the premise is available while the hypothesis is being encoded. Reported test accuracy for that baseline is 77.6; the single-stream [[conditional-encoding]] reaches 80.9, a 3.3-point gain, while using about 3.8M parameters against roughly 10M. A hand-engineered lexicalized classifier — BLEU between the sentences, length difference, word overlap, uni- and bigrams, part-of-speech tags, cross uni- and bigrams — scores 78.2, so the single-stream reader also passes it by 2.7 points. The paper's explanation for the gain is that information can flow from the premise computation into the hypothesis computation, letting the model check for contradictions and entailments word by word rather than build and then compare two full sentence meanings. Two confounds are acknowledged: the models use word2vec rather than GloVe embeddings, and do not fine-tune them. The smaller train-to-test drop for the single-stream models leads the authors to suggest that fine-tuning word embeddings may itself be a source of overfitting. These are accuracy comparisons on one dataset, and the paper frames the interpretation as an argument rather than a demonstration.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 2.2 for the two-encoder setup; Table 1 rows 'LSTM', 'Lexicalized classifier' and 'Conditional encoding, shared'; the 'Conditional Encoding' paragraph of Section 4 for the 3.3-point claim and the word-embedding caveats.", "ownerPaper": "1509.06664", "sources": {"paperId": "1509.06664", "note": "Section 2.2 for the two-encoder setup; Table 1 rows 'LSTM', 'Lexicalized classifier' and 'Conditional encoding, shared'; the 'Conditional Encoding' paragraph of Section 4 for the 3.3-point claim and the word-embedding caveats.", "sections": [], "pages": []}}], "items": [], "edges": [], "themes": [], "pages": [], "narrative": null, "insights": null, "refs": {"accessed": []}};
